const body = $input.first().json;
const content = body.content || '';
const person = body.person_name || 'unknown';
const docId = body.doc_id || null;
const patterns = [
  { re: /收缩压[：:]?\s*(\d+)/, name: '收缩压', unit: 'mmHg', max: 140, ref: '<140' },
  { re: /舒张压[：:]?\s*(\d+)/, name: '舒张压', unit: 'mmHg', max: 90, ref: '<90' },
  { re: /空腹血糖[：:]?\s*([\d.]+)/, name: '空腹血糖', unit: 'mmol/L', max: 6.1, ref: '3.9-6.1' },
  { re: /总胆固醇[：:]?\s*([\d.]+)/, name: '总胆固醇', unit: 'mmol/L', max: 5.2, ref: '<5.2' },
  { re: /甘油三酯[：:]?\s*([\d.]+)/, name: '甘油三酯', unit: 'mmol/L', max: 1.7, ref: '<1.7' },
  { re: /尿酸[：:]?\s*(\d+)/, name: '尿酸', unit: 'umol/L', max: 420, ref: '150-420' },
];
const out = [];
patterns.forEach(p => {
  const m = content.match(p.re);
  if (m) {
    const val = parseFloat(m[1]);
    out.push({
      json: {
        person_name: person,
        metric_name: p.name,
        metric_value: val,
        unit: p.unit,
        reference_range: p.ref,
        is_abnormal: val > p.max,
        source_doc_id: docId,
      }
    });
  }
});
return out;

const items = $input.all();
const abnormal = items.filter(i => i.json.is_abnormal);
return [{ json: {
  total: items.length,
  abnormal_count: abnormal.length,
  abnormal: abnormal.map(i => i.json.metric_name + ': ' + i.json.metric_value + i.json.unit),
  privacy_note: '全程规则提取，未调用任何模型'
}}];
